import type { BankQuestion } from "@/lib/bank";

/** Human Physiology: Digestion, Breathing, Circulation, Excretion (Biology (NEET)): 133 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"bio-human-physiology-systems-1","question":"The enzyme in saliva that begins the digestion of starch is:","options":["Pepsin of gastric juice","Salivary amylase (ptyalin)","Pancreatic lipase (steapsin)","Lysozyme of saliva"],"answer":1,"explanation":"Salivary amylase hydrolyses about 30% of starch to maltose at pH 6.8. Lysozyme in saliva is antibacterial, not digestive; pepsin acts on proteins in the stomach.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-2","question":"The functional unit of the human kidney is the:","options":["Nephron","Glomerulus","Bowman’s capsule","Renal pyramid"],"answer":0,"explanation":"Each kidney has nearly one million nephrons, each consisting of a glomerulus and a renal tubule (Bowman’s capsule, PCT, loop of Henle, DCT). The glomerulus is only a part of the nephron.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-3","question":"In a normal adult at rest, the cardiac output is approximately:","options":["70 mL per minute","500 mL per minute","5000 mL per minute","7200 mL per minute"],"answer":2,"explanation":"Cardiac output = stroke volume × heart rate = 70 mL × 72 per minute ≈ 5000 mL (5 L) per minute. 70 mL is the stroke volume alone, 500 mL is the tidal volume of the lungs, and 7200 mL comes from wrongly taking a 100 mL stroke volume.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-4","question":"Which enzyme is secreted by the gastric glands in an inactive form and is activated by HCl?","options":["Trypsinogen","Chymotrypsinogen","Procarboxypeptidase","Pepsinogen"],"answer":3,"explanation":"Chief (peptic) cells secrete pepsinogen, which HCl converts to active pepsin. Trypsinogen, chymotrypsinogen and procarboxypeptidase are pancreatic proenzymes activated in the intestine.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-5","question":"The volume of air inspired or expired during a normal breath is called the tidal volume and is approximately:","options":["150 mL","2500 mL","1200 mL","500 mL"],"answer":3,"explanation":"Tidal volume is about 500 mL; a healthy adult inspires/expires 6000–8000 mL per minute. 1100–1200 mL is the residual volume; 2500–3000 mL is the inspiratory reserve volume.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-6","question":"The pacemaker of the human heart, the sino-atrial node, is located in the:","options":["Upper right corner of the right atrium","Lower left corner of the right atrium","Interventricular septum","Wall of the left ventricle"],"answer":0,"explanation":"The SAN lies in the right upper corner of the right atrium and generates 70–75 action potentials per minute. The AV node is in the lower left corner of the right atrium near the atrio-ventricular septum.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-7","question":"The counter-current mechanism that concentrates urine involves the:","options":["Glomerulus and Bowman’s capsule","Loop of Henle and the vasa recta","Proximal and distal convoluted tubules","Collecting duct and renal pelvis"],"answer":1,"explanation":"The U-shaped loop of Henle and the parallel hairpin-shaped vasa recta form two counter-current systems that build an osmotic gradient (300 to 1200 mOsmol/L) in the medullary interstitium.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-8","question":"Which digestive secretion contains NO enzymes yet is essential for fat digestion?","options":["Bile","Pancreatic juice","Succus entericus","Gastric juice"],"answer":0,"explanation":"Bile contains bile salts, bile pigments (bilirubin, biliverdin), cholesterol and phospholipids but no enzymes. Bile salts emulsify fats into micelles and activate lipases.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-9","question":"The oxygen–haemoglobin dissociation curve is:","options":["A straight line","Hyperbolic","Sigmoid","Parabolic"],"answer":2,"explanation":"Because binding of O₂ to one haem increases the affinity of the others, percentage saturation plotted against pO₂ gives a sigmoid curve. It shifts right (lower affinity) with high pCO₂, high H⁺ and higher temperature, as in tissues.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-10","question":"A person has tidal volume 500 mL, inspiratory reserve volume 2500 mL, expiratory reserve volume 1000 mL and residual volume 1200 mL. The functional residual capacity (FRC) is:","options":["1500 mL","2200 mL","4000 mL","5200 mL"],"answer":1,"explanation":"FRC = ERV + RV = 1000 + 1200 = 2200 mL, the air left after a normal expiration. Vital capacity would be 500 + 2500 + 1000 = 4000 mL and total lung capacity 5200 mL.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-11","question":"In a standard ECG, the QRS complex represents:","options":["Depolarisation of the atria","Depolarisation of the ventricles","Repolarisation of the ventricles","Repolarisation of the atria"],"answer":1,"explanation":"P wave = atrial depolarisation, QRS = ventricular depolarisation (start of ventricular systole), T wave = ventricular repolarisation (end of systole). Atrial repolarisation is masked by the QRS. Counting QRS complexes gives the heart rate.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-12","question":"In a cardiac cycle lasting 0.8 s, the durations of atrial systole, ventricular systole and joint diastole are respectively:","options":["0.1 s, 0.3 s, 0.4 s","0.3 s, 0.1 s, 0.4 s","0.2 s, 0.2 s, 0.4 s","0.1 s, 0.4 s, 0.3 s"],"answer":0,"explanation":"Atrial systole lasts about 0.1 s, ventricular systole about 0.3 s, and both chambers then relax in joint diastole for about 0.4 s, totalling 0.8 s at 72 beats per minute.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-13","question":"The glomerular filtration rate in a healthy person is about 125 mL per minute. This amounts to roughly how much filtrate per day?","options":["18 L","180 L","1.5 L","1800 L"],"answer":1,"explanation":"125 mL/min × 1440 min = 180,000 mL = 180 L per day, of which about 99% is reabsorbed to give 1–1.5 L of urine.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-14","question":"Atrial natriuretic factor (ANF), released when blood flow to the atria increases, causes:","options":["Vasoconstriction and a rise in blood pressure","Vasodilation and a fall in blood pressure","Release of renin from the JGA","Increased reabsorption of Na⁺ by the DCT"],"answer":1,"explanation":"ANF is a check on the renin–angiotensin mechanism: it causes vasodilation and thereby lowers blood pressure, reducing the stretch on the atrial walls that triggered it.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-15","question":"The largest fraction of CO₂ transported by blood is carried as:","options":["Dissolved CO₂ in plasma (about 70%)","Carbamino-haemoglobin (about 70%)","Bicarbonate ions (about 70%)","Carbonic acid in RBCs (about 50%)"],"answer":2,"explanation":"About 70% of CO₂ travels as HCO₃⁻ (formed in RBCs by carbonic anhydrase), 20–25% as carbamino-haemoglobin and only about 7% dissolved in plasma.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-16","question":"Under normal physiological conditions, every 100 mL of oxygenated blood delivers to the tissues about:","options":["4 mL of O₂","5 mL of O₂","20 mL of O₂","1 mL of O₂"],"answer":1,"explanation":"Every 100 mL of oxygenated blood can deliver about 5 mL of O₂ to the tissues, while every 100 mL of deoxygenated blood delivers about 4 mL of CO₂ to the alveoli.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-17","question":"Trypsinogen, secreted by the pancreas, is converted into active trypsin by:","options":["HCl secreted by oxyntic cells","Pepsin in the gastric chyme","Bile salts released from the gall bladder","Enterokinase of the intestinal mucosa"],"answer":3,"explanation":"Enterokinase (enteropeptidase) from the intestinal mucosa activates trypsinogen to trypsin; trypsin in turn activates chymotrypsinogen and procarboxypeptidase. HCl activates only pepsinogen in the stomach.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-18","question":"Chymotrypsin, a pancreatic enzyme acting at the alkaline pH of the small intestine, converts:","options":["Starch and glycogen into maltose","Dipeptides into free amino acids","Proteins and peptones into dipeptides","Fats into fatty acids and monoglycerides"],"answer":2,"explanation":"Trypsin, chymotrypsin and carboxypeptidase of pancreatic juice break proteins, peptones and proteoses into dipeptides; dipeptidases of succus entericus then release amino acids.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-19","question":"How many of the following statements about the counter-current mechanism are correct?\n(i) The descending limb of the loop of Henle is permeable to water but almost impermeable to electrolytes.\n(ii) The ascending limb is impermeable to water but allows transport of electrolytes.\n(iii) NaCl and urea are the solutes that maintain the medullary interstitial gradient.\n(iv) The osmolarity rises from about 300 mOsmol/L in the cortex to about 1200 mOsmol/L in the inner medulla.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four statements are NCERT facts. NaCl is transported by the ascending limb and exchanged with the descending limb of the vasa recta, and urea diffuses in from the collecting duct, building the gradient that lets the collecting duct concentrate the filtrate.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-20","question":"Match the gastrointestinal hormone with its action.\nA. Gastrin — 1. Stimulates secretion of water and bicarbonate ions from the pancreas\nB. Secretin — 2. Inhibits gastric secretion and motility\nC. Cholecystokinin (CCK) — 3. Stimulates secretion of HCl and pepsinogen by gastric glands\nD. Gastric inhibitory peptide (GIP) — 4. Stimulates the gall bladder and secretion of pancreatic enzymes","options":["A-3, B-4, C-1, D-2","A-1, B-3, C-2, D-4","A-3, B-1, C-4, D-2","A-4, B-1, C-3, D-2"],"answer":2,"explanation":"Gastrin acts on gastric glands; secretin on the pancreatic duct cells (bicarbonate); CCK on the pancreas (enzymes) and gall bladder (bile); GIP inhibits gastric secretion. All four are peptide hormones of the gastrointestinal mucosa.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-21","question":"Assertion (A): Oxygen binds to haemoglobin in the alveoli and dissociates from it in the tissues.\nReason (R): The alveoli have high pO₂, low pCO₂, low H⁺ concentration and lower temperature, whereas the tissues have the opposite conditions.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"These four factors determine the affinity of haemoglobin for O₂: conditions in the alveoli favour oxyhaemoglobin formation, while high pCO₂, high H⁺ and higher temperature in tissues shift the curve to the right and favour dissociation.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-22","question":"The partial pressures (mm Hg) of O₂ and CO₂ in alveolar air are respectively:","options":["159 and 0.3","104 and 40","95 and 40","40 and 45"],"answer":1,"explanation":"Alveolar air: pO₂ 104, pCO₂ 40. Atmospheric air: 159 and 0.3; oxygenated blood: 95 and 40; deoxygenated blood and tissues: 40 and 45. Gradients of 64 mm Hg (O₂) and 5 mm Hg (CO₂) drive diffusion at the alveoli.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-23","question":"How many of the following statements about the human digestive system are correct?\n(i) Human teeth are thecodont, monophyodont and heterodont, with the dental formula 2123/2123.\n(ii) The pancreas, the largest gland of the body, weighs about 1.2–1.5 kg in an adult.\n(iii) Bile pigments bilirubin and biliverdin are breakdown products of haemoglobin.\n(iv) Chief (peptic) cells of the gastric glands secrete HCl.","options":["Only 1","Only 2","Only 3","All 4"],"answer":0,"explanation":"Only (iii) is correct. Human teeth are diphyodont (two sets), the liver (not pancreas) is the largest gland at 1.2–1.5 kg, and HCl is secreted by oxyntic cells while chief cells secrete pepsinogen.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-24","question":"Match the respiratory disorder with its description.\nA. Asthma — 1. Alveolar walls are damaged, reducing the respiratory surface; a major cause is cigarette smoking\nB. Emphysema — 2. Difficulty in breathing due to inflammation of bronchi and bronchioles\nC. Silicosis / asbestosis — 3. Proliferation of fibrous tissue in the upper lung after long exposure to dust in grinding or stone-breaking industries","options":["A-2, B-1, C-3","A-1, B-2, C-3","A-2, B-3, C-1","A-3, B-1, C-2"],"answer":0,"explanation":"Asthma is a bronchial inflammation causing wheezing; emphysema is chronic loss of alveolar surface, typically from smoking; occupational disorders such as silicosis result from inhaled dust causing fibrosis.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-25","question":"How many of the following statements about the human heart are correct?\n(i) At rest the heart beats about 72 times per minute with a stroke volume of about 70 mL, giving a cardiac output of about 5 L per minute.\n(ii) The first heart sound (lub) is due to closure of the tricuspid and bicuspid valves.\n(iii) The AV bundle divides into right and left bundle branches that end in Purkinje fibres in the ventricular musculature.\n(iv) The SA node can generate about 70–75 action potentials per minute and is therefore the pacemaker.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct NCERT statements. The second heart sound (dub) is from closure of the semilunar valves, and the cardiac output of athletes is higher because their stroke volume is larger.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-26","question":"How many of the following statements about tubular function in the nephron are correct?\n(i) The PCT reabsorbs nearly all essential nutrients and 70–80% of electrolytes and water.\n(ii) The DCT carries out conditional reabsorption of Na⁺ and water, and selective secretion of H⁺, K⁺ and NH₃.\n(iii) The collecting duct allows passage of small amounts of urea into the medullary interstitium.\n(iv) The ascending limb of the loop of Henle is freely permeable to water.","options":["Only 1","Only 2","Only 3","All 4"],"answer":2,"explanation":"(i), (ii) and (iii) are correct. (iv) is false: the ascending limb is impermeable to water (it actively or passively transports electrolytes), so the filtrate becomes dilute as it rises toward the cortex.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-27","question":"A fall in glomerular blood pressure activates the juxtaglomerular apparatus to release renin. Which of the following is NOT an effect of the resulting angiotensin II?","options":["Constriction of blood vessels, raising glomerular blood pressure and GFR","Stimulation of aldosterone release from the adrenal cortex","Increased reabsorption of Na⁺ and water from the distal parts of the tubule via aldosterone","Suppression of ADH release so that more water is lost in urine"],"answer":3,"explanation":"Renin converts angiotensinogen to angiotensin I and then II, a potent vasoconstrictor that raises GFR and triggers aldosterone, restoring blood pressure and volume. It does not promote water loss; that would defeat the purpose of the mechanism.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-28","question":"Assertion (A): Most of the CO₂ produced by tissues is transported in the blood as bicarbonate.\nReason (R): RBCs contain a very high concentration of carbonic anhydrase, which catalyses CO₂ + H₂O ⇌ H₂CO₃ ⇌ HCO₃⁻ + H⁺ in both directions.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"At the tissues (high pCO₂) the enzyme drives bicarbonate formation; at the alveoli (low pCO₂) the reaction reverses and CO₂ is released. Plasma contains only minute amounts of the enzyme, so RBCs do the work.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-29","question":"A person has a GFR of 125 mL per minute and produces 1.8 L of urine per day. What percentage of the filtrate is reabsorbed by the tubules?","options":["About 90%","About 99%","About 1%","About 80%"],"answer":1,"explanation":"Filtrate per day = 125 × 1440 = 180,000 mL = 180 L. Urine = 1.8 L, i.e. 1% of the filtrate is excreted, so 99% is reabsorbed, mostly in the PCT.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-30","question":"How many of the following statements about human circulation are correct?\n(i) The hepatic portal vein carries blood from the intestine to the liver before it reaches the systemic circulation.\n(ii) A special coronary system supplies the cardiac musculature.\n(iii) Double circulation keeps oxygenated and deoxygenated blood completely separate, allowing efficient supply of oxygen to the body.\n(iv) The pulmonary veins carry deoxygenated blood from the lungs to the left atrium.","options":["Only 1","Only 2","Only 3","All 4"],"answer":2,"explanation":"(i), (ii) and (iii) are correct. (iv) is false: pulmonary veins are the only veins carrying oxygenated blood (from the lungs to the left atrium); the pulmonary artery carries deoxygenated blood from the right ventricle.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-31","question":"In a healthy adult human, the normal systolic/diastolic blood pressure is about:","options":["80/120 mm Hg","120/80 mm Hg","140/90 mm Hg","100/60 mm Hg"],"answer":1,"explanation":"120 mm Hg is the systolic (pumping) and 80 mm Hg the diastolic (resting) pressure. 140/90 or higher indicates hypertension.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-32","question":"The oxyntic (parietal) cells of the gastric glands secrete:","options":["HCl and intrinsic factor","Gastrin and secretin","Mucus and bicarbonate","Pepsinogen and prorennin"],"answer":0,"explanation":"Oxyntic cells secrete HCl and intrinsic factor (needed for vitamin B₁₂ absorption). Peptic or chief cells secrete pepsinogen, and mucus neck cells secrete mucus.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-33","question":"Erythroblastosis foetalis can occur when:","options":["An Rh-negative mother carries a second Rh-positive foetus","An Rh-positive mother carries an Rh-negative foetus","Both parents are Rh-negative and the foetus too","The mother has blood group O and the foetus has blood group O"],"answer":0,"explanation":"In the first pregnancy the Rh-ve mother is exposed to Rh antigens at delivery and makes anti-Rh antibodies; in a later Rh+ve pregnancy these antibodies cross the placenta and destroy foetal RBCs. Anti-Rh antibodies given after the first delivery prevent it.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-34","question":"A person with blood group AB is called a universal recipient because:","options":["The blood is always Rh-negative","The plasma has both anti-A and anti-B antibodies","The plasma has no anti-A or anti-B antibodies","The RBCs have no antigens"],"answer":2,"explanation":"AB individuals have both antigens on RBCs and neither antibody in plasma, so they can receive blood of any ABO group. Group O, with no antigens, is the universal donor.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-35","question":"Fatty acids and glycerol absorbed in the intestine are re-formed into very small, protein-coated fat globules called chylomicrons, which are transported into:","options":["The hepatic portal vein","The bile duct","The blood capillaries of the villi directly","The lacteals (lymph vessels) of the villi"],"answer":3,"explanation":"Insoluble fatty acids and glycerol enter micelles, are taken into the mucosa and repackaged as chylomicrons, which pass into the lacteals and finally into the blood.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-36","question":"A person has tidal volume 500 mL, inspiratory reserve volume 3000 mL and expiratory reserve volume 1100 mL. The vital capacity is:","options":["4600 mL","4100 mL","5800 mL","3500 mL"],"answer":0,"explanation":"VC = ERV + TV + IRV = 1100 + 500 + 3000 = 4600 mL. Adding a residual volume of 1200 mL would give the total lung capacity (5800 mL).","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-37","question":"Which type of white blood cell is the least abundant in human blood?","options":["Basophils","Neutrophils","Monocytes","Lymphocytes"],"answer":0,"explanation":"Neutrophils are the most abundant (60–65%) and basophils the least (0.5–1%); basophils secrete histamine, serotonin and heparin and are involved in inflammation.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-38","question":"RBCs of a healthy adult have an average life span of about 120 days, after which they are destroyed mainly in the:","options":["Thymus","Bone marrow","Kidney","Spleen"],"answer":3,"explanation":"The spleen is called the graveyard of RBCs. RBCs are formed in the red bone marrow, and a healthy adult has 5 to 5.5 million RBCs per mm³.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-39","question":"How many of the following statements about disorders of the excretory system are correct?\n(i) In uremia, urea accumulates in the blood and can be removed by haemodialysis.\n(ii) Renal calculi are stones or insoluble masses of crystallised salts (oxalates, etc.) formed within the kidney.\n(iii) Glomerulonephritis is inflammation of the glomeruli of the kidney.\n(iv) An adult human excretes, on average, 25–30 g of urea per day.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Kidney transplantation is the ultimate method for correcting acute renal failure.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-40","question":"Match the circulatory disorder with its description.\nList I: (A) Hypertension (B) Coronary artery disease (C) Angina (D) Heart failure\nList II: (1) Acute chest pain when not enough oxygen reaches the heart muscle (2) Blood pressure of 140/90 mm Hg or higher (3) The heart does not pump blood effectively; congestion of the lungs is a main symptom (4) Deposits of calcium, fat, cholesterol and fibrous tissue narrow the arteries supplying the heart","options":["A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1","A-2, B-4, C-1, D-3","A-2, B-1, C-4, D-3"],"answer":2,"explanation":"Hypertension is BP ≥ 140/90; CAD (atherosclerosis) narrows the coronary arteries; angina is chest pain from inadequate oxygen to the heart muscle; heart failure is ineffective pumping, sometimes called congestive heart failure.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-41","question":"A person's stroke volume is 80 mL and cardiac output is 6 litres per minute. What is the duration of one cardiac cycle?","options":["1.0 s","0.75 s","0.8 s","0.6 s"],"answer":2,"explanation":"Heart rate = cardiac output ÷ stroke volume = 6000 ÷ 80 = 75 beats per minute; cycle duration = 60 ÷ 75 = 0.8 s.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-42","question":"Assertion (A): The human heart is called myogenic.\nReason (R): The normal activities of the heart are auto-regulated by specialised muscles called nodal tissue.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A: the SAN, part of the nodal musculature, generates the action potentials that start each beat, so the heart beat originates in muscle, not nerves.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-43","question":"How many of the following statements about absorption are correct?\n(i) Amino acids, glucose and electrolytes like Na⁺ are absorbed into the blood by active transport.\n(ii) Fatty acids and glycerol, being insoluble, are first incorporated into small droplets called micelles.\n(iii) No absorption takes place in the stomach.\n(iv) Fats are absorbed directly into the blood capillaries of the villi.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only (i) and (ii) are correct. The stomach absorbs water, simple sugars and alcohol, and fats travel as chylomicrons into the lacteals, not directly into blood capillaries.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-44","question":"Which of the following is NOT present in the succus entericus (intestinal juice)?","options":["Trypsinogen","Dipeptidases","Nucleosidases","Disaccharidases such as maltase"],"answer":0,"explanation":"Succus entericus, formed by brush border and goblet cells, contains disaccharidases, dipeptidases, lipases and nucleosidases. Trypsinogen is a pancreatic secretion.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-45","question":"How many of the following statements about the regulation of respiration are correct?\n(i) The respiratory rhythm centre is present in the medulla.\n(ii) The pneumotaxic centre in the pons can reduce the duration of inspiration and thereby alter the respiratory rate.\n(iii) A chemosensitive area next to the rhythm centre is highly sensitive to CO₂ and hydrogen ions.\n(iv) Receptors associated with the aortic arch and carotid artery can recognise changes in CO₂ and H⁺ concentration.","options":["Only 1","Only 2","Only 3","All 4"],"answer":3,"explanation":"All four are correct. The rhythm centre is in the medulla, the pneumotaxic centre in the pons shortens inspiration, the chemosensitive area responds to CO₂ and H⁺, and aortic and carotid receptors also sense CO₂ and H⁺.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-human-physiology-systems-46", "question": "Animals that excrete nitrogenous waste mainly as ammonia, such as many bony fishes and aquatic amphibians, are called:", "options": ["Guanotelic", "Uricotelic", "Ammonotelic", "Ureotelic"], "answer": 2, "explanation": "Ammonotelic animals excrete ammonia, which is highly toxic and needs a lot of water, so the habit suits aquatic animals such as bony fishes, aquatic amphibians and aquatic insects.", "difficulty": "easy", "source": "NEET pattern"},
  {"id":"bio-human-physiology-systems-47","question":"The glomerulus together with Bowman's capsule is called the:","options":["Juxtaglomerular apparatus","Collecting duct","Malpighian body","Loop of Henle"],"answer":2,"explanation":"The glomerulus and Bowman's capsule together form the Malpighian body or renal corpuscle, located in the cortex. The renal tubule continues from it as PCT, loop of Henle and DCT.","difficulty":"easy","source":"NEET pattern"},
  {"id": "bio-human-physiology-systems-48", "question": "Among plasma proteins, albumins mainly help in:", "options": ["Defence mechanisms", "Blood clotting", "Oxygen transport", "Osmotic balance"], "answer": 3, "explanation": "Plasma proteins form 6–8% of plasma: fibrinogen is needed for clotting, globulins for defence, and albumins for osmotic balance. Oxygen is carried by haemoglobin in RBCs.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-human-physiology-systems-49", "question": "Blood platelets (thrombocytes) are cell fragments produced from:", "options": ["Megakaryocytes", "Monocytes", "Lymphocytes", "Erythroblasts"], "answer": 0, "explanation": "Platelets are cell fragments produced from megakaryocytes, special cells in the bone marrow. A reduction in their number can lead to clotting disorders and excessive loss of blood.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-human-physiology-systems-50", "question": "Which group consists only of uricotelic animals?", "options": ["Reptiles, birds, land snails and insects", "Bony fishes and aquatic insects", "Mammals, frogs and marine fishes", "Humans, earthworms and cartilaginous fishes"], "answer": 0, "explanation": "Reptiles, birds, land snails and insects excrete uric acid as pellets or paste with minimal water loss. Mammals and terrestrial amphibians are ureotelic, and bony fishes are ammonotelic.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-human-physiology-systems-51", "question": "In the small intestine, fats are absorbed through special lymphatic vessels in the villi called:", "options": ["Vasa recta", "Pulmonary vessels", "Lacteals", "Capillaries of the hepatic portal system"], "answer": 2, "explanation": "Lymph, a colourless fluid with specialised lymphocytes, is carried by the lymphatic system; lacteals in the intestinal villi absorb fats. The hepatic portal vein carries other absorbed nutrients to the liver.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-human-physiology-systems-52", "question": "Inspiration in humans occurs when:", "options": ["The internal intercostal muscles contract", "The intra-pulmonary pressure is lower than the atmospheric pressure", "The intra-pulmonary pressure is higher than the atmospheric pressure", "The diaphragm relaxes and becomes dome-shaped"], "answer": 1, "explanation": "During inspiration the diaphragm and external intercostal muscles contract, increasing the thoracic and pulmonary volume; this lowers the intra-pulmonary pressure below atmospheric, so air moves into the lungs.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "bio-human-physiology-systems-53", "question": "The normal haemoglobin content of blood in a healthy individual is:", "options": ["1.5–3.5 g per 100 mL", "25–30 g per 100 mL", "12–16 g per 100 mL", "5–5.5 g per 100 mL"], "answer": 2, "explanation": "Blood normally has 12–16 g of haemoglobin per 100 mL. 5–5.5 million per mm³ is the RBC count, not the haemoglobin content, a frequent mix-up.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-human-physiology-systems-54", "question": "Which white blood cells, forming about 2–3% of WBCs, resist infections and are associated with allergic reactions?", "options": ["Neutrophils", "Basophils", "Monocytes", "Eosinophils"], "answer": 3, "explanation": "Eosinophils (2–3%) resist infections and are linked to allergy. Neutrophils (60–65%) and monocytes (6–8%) are phagocytic, and basophils secrete histamine, serotonin and heparin.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-human-physiology-systems-55", "question": "Under normal physiological conditions, every 100 mL of deoxygenated blood delivers approximately how much CO₂ to the alveoli?", "options": ["4 mL", "45 mL", "20 mL", "5 mL"], "answer": 0, "explanation": "About 4 mL of CO₂ is delivered to the alveoli by every 100 mL of deoxygenated blood. The oxygen delivered to tissues per 100 mL of oxygenated blood is about 5 mL.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-human-physiology-systems-56", "question": "A healthy human can inspire or expire approximately how much air per minute?", "options": ["20,000–25,000 mL", "6000–8000 mL", "1000–1100 mL", "500–600 mL"], "answer": 1, "explanation": "With about 500 mL tidal volume and 12–16 breaths per minute, a healthy person moves about 6000–8000 mL of air per minute.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-human-physiology-systems-57", "question": "The vasa recta is absent or highly reduced in:", "options": ["Cortical nephrons", "Both kidneys of all mammals", "Juxta medullary nephrons", "The collecting duct system"], "answer": 0, "explanation": "In cortical nephrons, which form the majority, the loop of Henle is short and extends only a little into the medulla, and the vasa recta is absent or highly reduced. Juxta medullary nephrons have long loops and a well-developed vasa recta.", "difficulty": "hard", "source": "NEET pattern"},
  {"id":"bio-human-physiology-systems-58","question":"The filtration membrane through which blood is filtered into Bowman's capsule is formed by three layers. Which of the following is one of them?","options":["The smooth muscle layer of the afferent arteriole wall","Basement membrane between endothelium and capsule epithelium","The cuboidal brush-bordered epithelium lining the proximal tubule","The thin epithelium of the descending loop of Henle"],"answer":1,"explanation":"The three layers are the endothelium of the glomerular blood vessels, the epithelium of Bowman's capsule, and the basement membrane between them. The capsule epithelium has podocytes with filtration slits.","difficulty":"hard","source":"NEET pattern"},
  {"id": "bio-human-physiology-systems-59", "question": "The presence of glucose (glycosuria) and ketone bodies (ketonuria) in urine indicates:", "options": ["Renal calculi", "Gout", "Diabetes mellitus", "Glomerulonephritis"], "answer": 2, "explanation": "Analysis of urine helps in clinical diagnosis: glucose and ketone bodies in urine are indicative of diabetes mellitus. Renal calculi are crystallised salt stones, and gout involves uric acid in joints.", "difficulty": "hard", "source": "NEET pattern"},
  {"id": "bio-human-physiology-systems-60", "question": "Match the wave of a standard ECG with the event it represents.\nList I: (A) P wave (B) QRS complex (C) T wave (D) End of the T wave\nList II: (1) Return of the ventricles from excited to normal state (repolarisation) (2) Excitation (depolarisation) of the atria (3) End of systole (4) Depolarisation of the ventricles, initiating ventricular contraction", "options": ["A-2, B-4, C-1, D-3", "A-4, B-2, C-1, D-3", "A-2, B-1, C-4, D-3", "A-2, B-4, C-3, D-1"], "answer": 0, "explanation": "The P wave is atrial depolarisation, QRS is ventricular depolarisation that starts ventricular contraction, the T wave is ventricular repolarisation, and the end of the T wave marks the end of systole.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-human-physiology-systems-61", "question": "Match the animal group with its circulation.\nList I: (A) Fishes (B) Amphibians and most reptiles (C) Crocodiles, birds and mammals (D) Arthropods and molluscs\nList II: (1) Open circulatory system (2) Two-chambered heart pumping only deoxygenated blood; single circulation (3) Three-chambered heart with mixing of blood in the single ventricle; incomplete double circulation (4) Four-chambered heart with complete separation; double circulation", "options": ["A-1, B-3, C-4, D-2", "A-2, B-3, C-4, D-1", "A-3, B-2, C-4, D-1", "A-2, B-4, C-3, D-1"], "answer": 1, "explanation": "Fishes have a 2-chambered heart and single circulation; amphibians and most reptiles have a 3-chambered heart with mixed blood; crocodiles, birds and mammals have 4 chambers and complete double circulation; arthropods and molluscs have an open system.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-human-physiology-systems-62", "question": "Arrange the following events of blood coagulation in the correct order:\n(i) Thrombin converts fibrinogen into fibrin\n(ii) An injury stimulates platelets and damaged tissue to release certain factors\n(iii) Thrombokinase converts inactive prothrombin into thrombin\n(iv) A network of fibrin threads traps the formed elements, forming a clot", "options": ["(iii), (ii), (i), (iv)", "(ii), (iii), (i), (iv)", "(ii), (i), (iii), (iv)", "(i), (ii), (iii), (iv)"], "answer": 1, "explanation": "Injury releases factors that activate a cascade producing thrombokinase; it converts prothrombin to thrombin, which converts fibrinogen to fibrin; fibrin threads then trap blood cells to form a clot. Calcium ions are needed throughout.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-human-physiology-systems-63","question":"How many of the following statements about CO₂ transport are correct?\n(i) About 20–25% of CO₂ is carried by haemoglobin as carbamino-haemoglobin.\n(ii) About 70% of CO₂ is carried as bicarbonate.\n(iii) About 7% of CO₂ is carried in a dissolved state in plasma.\n(iv) Binding of CO₂ to haemoglobin is favoured by high pCO₂ and low pO₂.","options":["Only 1","Only 2","Only 3","All 4"],"answer":3,"explanation":"All four are correct: about 20–25% of CO₂ travels as carbamino-haemoglobin, 70% as bicarbonate and 7% dissolved, and carbamino-haemoglobin forms where pCO₂ is high and pO₂ low, as in the tissues.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-human-physiology-systems-64", "question": "Match the excretory structure with the animal group.\nList I: (A) Protonephridia (flame cells) (B) Nephridia (C) Malpighian tubules (D) Antennal (green) glands\nList II: (1) Insects such as cockroaches (2) Crustaceans such as prawns (3) Annelids such as earthworms (4) Platyhelminthes such as Planaria", "options": ["A-4, B-3, C-2, D-1", "A-4, B-3, C-1, D-2", "A-3, B-4, C-1, D-2", "A-4, B-1, C-3, D-2"], "answer": 1, "explanation": "Flame cells (protonephridia) are found in Platyhelminthes, some annelids and cephalochordates; nephridia in earthworms and other annelids; Malpighian tubules in insects; antennal or green glands in crustaceans like prawns.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-human-physiology-systems-65", "question": "A person has tidal volume 500 mL, inspiratory reserve volume 2500 mL, expiratory reserve volume 1100 mL and residual volume 1200 mL. The inspiratory capacity and total lung capacity are respectively:", "options": ["2500 mL and 5300 mL", "3000 mL and 4100 mL", "3000 mL and 5300 mL", "3600 mL and 5300 mL"], "answer": 2, "explanation": "Inspiratory capacity = TV + IRV = 500 + 2500 = 3000 mL. Total lung capacity = TV + IRV + ERV + RV = 500 + 2500 + 1100 + 1200 = 5300 mL. 4100 mL is the vital capacity.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "bio-human-physiology-systems-66", "question": "Assertion (A): The diffusing capacity of CO₂ across the respiratory membrane is much higher than that of O₂.\nReason (R): The solubility of CO₂ is 20–25 times higher than that of O₂.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. Because CO₂ is far more soluble, the amount of CO₂ that can diffuse per unit difference in partial pressure is much higher than that of O₂.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-human-physiology-systems-67","question":"How many of the following statements about human blood are correct?\n(i) Plasma constitutes nearly 45% of the blood.\n(ii) Plasma proteins constitute 90–92% of the plasma.\n(iii) A healthy adult man has on average 5–5.5 million RBCs per mm³ of blood.\n(iv) Blood normally contains 6000–8000 platelets per mm³.","options":["Only 1","Only 2","Only 3","All 4"],"answer":0,"explanation":"Only (iii) is correct. Plasma is about 55% of blood (formed elements 45%), water is 90–92% of plasma while proteins are 6–8%, and 6000–8000 per mm³ is the WBC count; platelets number 1,50,000–3,50,000.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-human-physiology-systems-68", "question": "Other organs also help in elimination of excretory wastes. Which statement is INCORRECT?", "options": ["Sebaceous glands eliminate sterols, hydrocarbons and waxes through sebum", "The lungs remove large amounts of CO₂ (about 200 mL per minute) and water every day", "The liver secretes bilirubin, biliverdin, cholesterol and degraded steroid hormones into bile", "The primary function of sweat is to eliminate large amounts of urea from the body"], "answer": 3, "explanation": "Sweat contains NaCl, small amounts of urea and lactic acid, but its primary function is to cool the body surface. The other three statements are correct NCERT facts.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-human-physiology-systems-69","question":"How many of the following statements about the human kidney are correct?\n(i) Each kidney of an adult is about 10–12 cm long, 5–7 cm wide, 2–3 cm thick and weighs 120–170 g.\n(ii) The hilum is a notch on the outer convex surface through which the ureter, blood vessels and nerves enter.\n(iii) The columns of Bertini are extensions of the medulla into the cortex.\n(iv) Each kidney has nearly one million nephrons.","options":["Only 1","Only 2","Only 3","All 4"],"answer":1,"explanation":"(i) and (iv) are correct. (ii) is wrong: the hilum lies on the inner concave surface. (iii) is reversed: the columns of Bertini are extensions of the cortex between the medullary pyramids.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "bio-human-physiology-systems-70", "question": "Which statement about the mechanism of breathing is INCORRECT?", "options": ["Contraction of the diaphragm increases the volume of the thoracic chamber in the antero-posterior axis", "Additional abdominal muscles cannot increase the strength of inspiration or expiration", "During expiration the intra-pulmonary pressure becomes slightly higher than the atmospheric pressure", "Contraction of the external intercostal muscles lifts the ribs and sternum, increasing the volume in the dorso-ventral axis"], "answer": 1, "explanation": "NCERT notes that with additional muscles in the abdomen we can increase the strength of both inspiration and expiration. The other three statements correctly describe breathing.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id":"bio-human-physiology-systems-71","question":"The largest gland of the human body, weighing about 1.2–1.5 kg in an adult, is the:","options":["Pancreas","Thyroid","Liver","Spleen"],"answer":2,"explanation":"The liver is the largest gland. Its hepatic cells secrete bile, which is stored and concentrated in the gall bladder. The pancreas is the second major digestive gland and has both exocrine and endocrine parts.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-72","question":"In insects, exchange of gases with the atmosphere takes place through:","options":["Gills on the abdomen","Lungs fed by spiracles","Their thin, moist body cuticle","A network of tracheal tubes"],"answer":3,"explanation":"Insects have tracheal tubes that carry air directly to their tissues. Most aquatic arthropods and molluscs use gills, earthworms use their moist cuticle, and terrestrial vertebrates use lungs.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-73","question":"In ureotelic animals such as mammals, ammonia produced by metabolism is converted into urea in the:","options":["Liver","Kidney","Spleen","Urinary bladder"],"answer":0,"explanation":"Ammonia is converted into urea in the liver and released into the blood. The kidneys then filter and excrete the urea; they do not make it.","difficulty":"easy","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-74","question":"In the duodenum, the sub-mucosal glands that help provide an alkaline medium protecting the mucosa from acid are:","options":["Brunner's glands","Crypts of Lieberkühn","Gastric glands","Islets of Langerhans"],"answer":0,"explanation":"Brunner's glands lie in the sub-mucosa of the duodenum. Together with mucus and pancreatic bicarbonate, their secretion gives an alkaline pH of about 7.8. Crypts of Lieberkühn are intestinal glands in the mucosa between the bases of villi.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-75","question":"The proteolytic enzyme in the gastric juice of infants that helps in the digestion of milk proteins is:","options":["Trypsin","Rennin","Lipase","Enterokinase"],"answer":1,"explanation":"Rennin, found in the gastric juice of infants, acts on milk proteins. Trypsin is a pancreatic enzyme that acts in the intestine, and enterokinase is an intestinal enzyme that activates trypsinogen.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-76","question":"The most abundant white blood cells in human blood, forming about 60–65% of the total WBCs, are:","options":["Lymphocytes","Monocytes","Neutrophils","Eosinophils"],"answer":2,"explanation":"Neutrophils (60–65%) are phagocytic cells. Lymphocytes form 20–25%, monocytes 6–8%, eosinophils 2–3%, and basophils are the fewest at 0.5–1%.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-77","question":"On average, an adult human excretes per day about:","options":["180 L of urine containing 25–30 g of urea","1–1.5 L of urine containing 250–300 g of urea","5 L of urine containing 2–3 g of urea","1–1.5 L of urine containing 25–30 g of urea"],"answer":3,"explanation":"About 1–1.5 L of urine is passed per day, carrying 25–30 g of urea. 180 L is the daily glomerular filtrate, nearly 99% of which is reabsorbed.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-78","question":"If a person's heart beats 100 times per minute, the duration of one cardiac cycle is:","options":["0.8 s","0.6 s","1.0 s","0.5 s"],"answer":1,"explanation":"Duration of one cycle = 60 s / 100 beats = 0.6 s. The textbook value of 0.8 s applies to a rate of about 72–75 beats per minute.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-79","question":"An open circulatory system, in which blood flows through open spaces or sinuses, is found in:","options":["Annelids and all chordates","Fishes and amphibians","Arthropods and molluscs","Birds and mammals"],"answer":2,"explanation":"In arthropods and molluscs, the heart pumps blood into vessels that open into spaces (sinuses). Annelids and chordates have a closed system in which blood always flows through closed vessels.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-80","question":"Which statement about the conducting part of the human respiratory system (external nostrils up to the terminal bronchioles) is INCORRECT?","options":["It clears inhaled air of foreign particles","It humidifies the inhaled air before it reaches the alveoli","It brings the inhaled air to body temperature","It is where O₂ and CO₂ diffuse between air and blood"],"answer":3,"explanation":"The conducting part transports, cleans, humidifies and warms the air. Gas exchange happens only in the respiratory (exchange) part, the alveoli and their ducts.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-81","question":"In the alveoli, the formation of oxyhaemoglobin is favoured by:","options":["High pO₂, low pCO₂, lower H⁺ concentration and lower temperature","Low pO₂, high pCO₂, higher H⁺ concentration and higher temperature","High pO₂, high pCO₂, higher H⁺ concentration and higher temperature","Low pO₂, low pCO₂, lower H⁺ concentration and lower temperature"],"answer":0,"explanation":"These alveolar conditions favour binding of O₂ to haemoglobin. The tissues have the opposite conditions (low pO₂, high pCO₂, high H⁺, higher temperature), which favour release of O₂.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-82","question":"In the cardiac cycle, atrial systole increases the flow of blood into the ventricles by about:","options":["30 per cent","70 per cent","100 per cent","10 per cent"],"answer":0,"explanation":"Most ventricular filling happens passively during joint diastole, when the AV valves are open. Atrial contraction adds only about 30 per cent more, which is the trap of choosing 70%.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-83","question":"Arrange the parts of the conducting system of the human heart in the order in which the impulse travels:\n(i) Purkinje fibres\n(ii) Atrio-ventricular node\n(iii) Sino-atrial node\n(iv) Bundle of His and its right and left branches","options":["(ii), (iii), (iv), (i)","(iii), (iv), (ii), (i)","(iii), (ii), (iv), (i)","(iii), (ii), (i), (iv)"],"answer":2,"explanation":"The impulse starts at the SAN (pacemaker), passes to the AVN, then the AV bundle (bundle of His) and its branches through the inter-ventricular septum, and finally the Purkinje fibres in the ventricular wall.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-84","question":"In a 6-second strip of a normal ECG, 7 QRS complexes are counted. The heart rate of the person is about:","options":["42 beats per minute","84 beats per minute","70 beats per minute","60 beats per minute"],"answer":2,"explanation":"Each QRS complex marks one ventricular beat. 7 beats in 6 s works out to 7 × 10 = 70 beats per minute.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-85","question":"Which statement about haemodialysis is correct?","options":["Heparin is added to the blood to speed up clotting in the dialyser","Blood is drawn from a vein and returned to an artery","Blood is cleared of wastes by active transport across the cellophane tube","Dialysing fluid matches plasma except for nitrogenous wastes"],"answer":3,"explanation":"Blood from a convenient artery is mixed with the anticoagulant heparin and passed through a coiled cellophane tube bathed in dialysing fluid. Wastes move out by diffusion along their concentration gradient. Anti-heparin is added before the blood is returned through a vein.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-86","question":"Besides increasing water reabsorption in the distal parts of the nephron, ADH can also affect kidney function by:","options":["Dilating the afferent arteriole, which lowers the GFR","Constricting blood vessels, raising blood pressure and GFR","Stimulating secretion of renin by the juxtaglomerular cells","Promoting excretion of Na⁺ and water by inhibiting aldosterone"],"answer":1,"explanation":"ADH has a constrictory effect on blood vessels. The resulting rise in blood pressure can increase glomerular blood flow and GFR. Release of Na⁺ and water (diuresis) is caused by ANF, not ADH.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-87","question":"A patient with blood group A needs a transfusion. Four donors are available with groups AB, B, O and A. How many of them are suitable donors?","options":["One","Two","Three","Four"],"answer":1,"explanation":"Group A plasma has anti-B antibodies, so the donor's RBCs must lack antigen B. Only group A and group O donors are suitable; AB and B cells carry antigen B and would agglutinate.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-88","question":"Which statement about the Rh blood group is correct?","options":["Nearly 80% of all humans worldwide are Rh-negative","The Rh antigen is found on the surface of white blood cells only","Anti-Rh antibodies are naturally present in the plasma of every Rh-negative person","Rh-negative people form anti-Rh antibodies only after exposure"],"answer":3,"explanation":"Anti-Rh antibodies form only after an Rh-negative person is exposed to Rh-positive cells, which is why Rh should also be matched before transfusion. Nearly 80% of humans are Rh-positive, and the antigen is on RBCs.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-89","question":"How many of the following statements about lymph (tissue fluid) are correct?\n(i) Tissue fluid has the same mineral distribution as plasma.\n(ii) Exchange of nutrients and gases between blood and cells occurs through this fluid.\n(iii) Lymph is a colourless fluid containing specialised lymphocytes.\n(iv) Lymph contains large numbers of RBCs, which give it oxygen-carrying capacity.\n(v) Fats are absorbed through lymph in the lacteals of intestinal villi.","options":["One","Two","Three","Four"],"answer":3,"explanation":"Statements (i), (ii), (iii) and (v) are correct. Lymph has no RBCs, which stay inside the capillaries, so (iv) is false. Lymphocytes in lymph take part in immune responses.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-90","question":"Assertion (A): When the urinary bladder fills, stretch receptors on its wall send signals to the CNS.\nReason (R): The CNS sends motor messages that contract the smooth muscles of the bladder and relax the urethral sphincter, releasing urine.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":1,"explanation":"Both statements are correct parts of the micturition reflex. R describes the response that follows the stimulus in A; it does not explain why the stretch receptors send signals, so it is not the explanation of A.","difficulty":"hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-91","question":"Match the site with its approximate partial pressure of oxygen (mm Hg).\nList I: (A) Atmospheric air (B) Alveoli (C) Deoxygenated blood (D) Oxygenated blood\nList II: (1) 40 (2) 95 (3) 159 (4) 104","options":["A-3, B-2, C-1, D-4","A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-3, B-4, C-2, D-1"],"answer":1,"explanation":"pO₂ is 159 mm Hg in atmospheric air, 104 in the alveoli, 95 in oxygenated blood and 40 in deoxygenated blood and tissues. These gradients drive O₂ from the alveoli into blood and from blood into the tissues.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-92","question":"At rest, a person's heart rate is 72 per minute and stroke volume 70 mL. During exercise the heart rate doubles and the stroke volume rises by 20%. The cardiac output during exercise is about:","options":["10.1 L per minute","5.0 L per minute","12.1 L per minute","14.5 L per minute"],"answer":2,"explanation":"Exercise heart rate = 144 per minute and stroke volume = 70 × 1.2 = 84 mL. Cardiac output = 144 × 84 = 12,096 mL, about 12.1 L per minute. Doubling the rate alone would give about 10.1 L.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-93","question":"Arrange the events of one cardiac cycle in the correct order, starting with the SAN impulse:\n(i) The semilunar valves close (second heart sound)\n(ii) The atria contract\n(iii) The AV valves close as the ventricles begin to contract\n(iv) The AV valves open as ventricular pressure falls\n(v) The semilunar valves open and blood enters the aorta and pulmonary artery","options":["(ii), (v), (iii), (i), (iv)","(iii), (ii), (v), (iv), (i)","(ii), (iii), (i), (v), (iv)","(ii), (iii), (v), (i), (iv)"],"answer":3,"explanation":"Atrial systole comes first. Ventricular systole then closes the AV valves (lub), and rising pressure opens the semilunar valves. When the ventricles relax, the semilunar valves close (dub), and as ventricular pressure falls further the AV valves open for the next filling.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-94","question":"How many of the following statements about the cardiac cycle and ECG are correct?\n(i) During joint diastole, the tricuspid and bicuspid valves are open and the semilunar valves are closed.\n(ii) Atrial systole and ventricular systole occur at the same time.\n(iii) The QRS complex represents repolarisation of the ventricles.\n(iv) The end of the T wave marks the end of ventricular systole.","options":["Exactly 1","Exactly 2","Exactly 3","Exactly 4"],"answer":1,"explanation":"(i) and (iv) are correct. (ii) is wrong: atrial systole comes before ventricular systole. (iii) is wrong: the QRS complex represents ventricular depolarisation; repolarisation of the ventricles is shown by the T wave.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-95","question":"A person's GFR is 125 mL per minute. If the PCT reabsorbs 75% of the filtrate, about how much filtrate enters the loop of Henle per minute?","options":["About 94 mL","About 125 mL","About 31 mL","About 1.25 mL"],"answer":2,"explanation":"Filtrate remaining after the PCT = 25% of 125 = 31.25 mL per minute. About 94 mL is the volume reabsorbed in the PCT, not what passes on to the loop.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-96","question":"At rest, every 100 mL of oxygenated blood delivers about 5 mL of O₂ to the tissues, and every 100 mL of deoxygenated blood delivers about 4 mL of CO₂ to the alveoli. With a cardiac output of 5 L per minute, the O₂ delivered to tissues and the CO₂ delivered to the alveoli per minute are about:","options":["25 mL and 20 mL","500 mL and 400 mL","200 mL and 250 mL","250 mL and 200 mL"],"answer":3,"explanation":"5000 mL of blood is 50 units of 100 mL. O₂ = 50 × 5 = 250 mL and CO₂ = 50 × 4 = 200 mL per minute. The reversed option swaps the two gases.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-97","question":"Match the enzyme with the reaction it catalyses.\nList I: (A) Nucleotidase (B) Nucleosidase (C) Dipeptidase (D) Lactase\nList II: (1) Nucleosides → sugars + bases (2) Lactose → glucose + galactose (3) Nucleotides → nucleosides (4) Dipeptides → amino acids","options":["A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4","A-3, B-1, C-4, D-2","A-4, B-1, C-3, D-2"],"answer":2,"explanation":"Nucleic acids are broken down step by step: nucleases give nucleotides, nucleotidases give nucleosides, and nucleosidases give sugars and bases. Dipeptidase gives amino acids, and lactase splits lactose into glucose and galactose.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-98","question":"A person has an inspiratory capacity of 3000 mL, a vital capacity of 4100 mL and a residual volume of 1200 mL. The functional residual capacity is:","options":["2300 mL","1100 mL","4200 mL","5300 mL"],"answer":0,"explanation":"ERV = VC − IC = 4100 − 3000 = 1100 mL, and FRC = ERV + RV = 1100 + 1200 = 2300 mL. 1100 mL is only the ERV, and 5300 mL is the total lung capacity.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-99","question":"Assertion (A): The two-chambered heart of fishes pumps oxygenated blood to all parts of the body.\nReason (R): In fishes, blood passes through the heart only once in each complete circuit (single circulation).","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":3,"explanation":"(A) is false: the fish heart pumps deoxygenated blood to the gills, and oxygenated blood goes from the gills directly to the body. (R) is true: this single circulation is why the fish heart handles only deoxygenated blood.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-100","question":"Assertion (A): Amphibians and most reptiles show incomplete double circulation.\nReason (R): Oxygenated blood from the left atrium and deoxygenated blood from the right atrium mix in their single ventricle.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both are true and R explains A. These animals have a three-chambered heart, so the single ventricle pumps out mixed blood. Crocodiles, birds and mammals have four chambers and complete double circulation.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"bio-human-physiology-systems-101","question":"A meal contains 50 g carbohydrate, 20 g protein and 10 g fat. Using the NCERT gross calorific values and physiologic values of these nutrients, by how much does the meal's gross calorific value exceed the energy it actually yields in the body?","options":["42.5 kcal","22.5 kcal","38.0 kcal","33.0 kcal"],"answer":0,"explanation":"Gross values are 4.1, 5.65 and 9.45 kcal/g; physiologic values are 4.0, 4.0 and 9.0 kcal/g. Difference = 50(0.1) + 20(1.65) + 10(0.45) = 5 + 33 + 4.5 = 42.5 kcal; most of the gap comes from protein.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-102","question":"A person has a vital capacity of 4600 mL, a functional residual capacity of 2300 mL and an expiratory reserve volume of 1100 mL. His total lung capacity is:","options":["6900 mL","5800 mL","5700 mL","3500 mL"],"answer":1,"explanation":"RV = FRC − ERV = 2300 − 1100 = 1200 mL, and TLC = VC + RV = 4600 + 1200 = 5800 mL. Adding VC and FRC (6900 mL) counts the ERV twice.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-103","question":"The pO₂ gradient between alveolar air (104 mm Hg) and deoxygenated blood (40 mm Hg) is much larger than the pCO₂ gradient (45 → 40 mm Hg), yet CO₂ is exchanged across the alveolar membrane as efficiently as O₂. The main reason is that:","options":["CO₂ is carried by haemoglobin, which releases it faster than it releases O₂","the diffusion membrane is thinner for CO₂ than it is for O₂ molecules","carbonic anhydrase in the alveolar wall actively pumps CO₂ into the air","the solubility of CO₂ is about 20–25 times higher than that of O₂"],"answer":3,"explanation":"Rate of diffusion depends on the pressure gradient and on solubility; CO₂ is 20–25 times more soluble than O₂, so the amount diffusing per unit gradient is much higher. The membrane is the same for both gases.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-104","question":"The trachea, a straight tube extending up to the mid-thoracic cavity, divides into the right and left primary bronchi at the level of the:","options":["3rd thoracic vertebra","7th cervical vertebra","5th thoracic vertebra","1st lumbar vertebra"],"answer":2,"explanation":"NCERT states that the trachea divides at the level of the 5th thoracic vertebra into the right and left primary bronchi, which then branch into secondary and tertiary bronchi and bronchioles.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-105","question":"How many of the following statements about the mechanism of breathing are correct?\n(i) Contraction of the diaphragm increases the volume of the thoracic chamber in the antero-posterior axis.\n(ii) Contraction of the external inter-costal muscles lifts the ribs and sternum, increasing the volume in the dorso-ventral axis.\n(iii) During inspiration the intra-pulmonary pressure becomes less than the atmospheric pressure.\n(iv) Expiration takes place when the intra-pulmonary pressure falls below the atmospheric pressure.\n(v) A healthy human breathes 12–16 times per minute.","options":["Two","Three","Four","Five"],"answer":2,"explanation":"Statements (i), (ii), (iii) and (v) are correct. Expiration occurs when the intra-pulmonary pressure rises ABOVE atmospheric pressure as the diaphragm and inter-costal muscles relax, so (iv) is wrong.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-106","question":"Which one of the following is INCORRECTLY matched with the value given in NCERT for a healthy adult human?","options":["Monocytes — 20 to 25 per cent of total WBCs","Platelets — 1.5 to 3.5 lakh per mm³ of blood","Haemoglobin — 12 to 16 g per 100 mL of blood","Total WBCs — 6000 to 8000 per mm³ of blood"],"answer":0,"explanation":"Lymphocytes form 20–25% of WBCs; monocytes are only about 6–8%. The other three values (platelets, haemoglobin and total leucocyte count) are as given in NCERT.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-107","question":"A sample of blood is allowed to clot and the clear fluid left behind (serum) is analysed. Compared with plasma, serum lacks:","options":["albumins needed for osmotic balance","fibrinogen and other clotting factors","globulins involved in defence mechanisms","glucose, amino acids and mineral ions"],"answer":1,"explanation":"Plasma without the clotting factors is called serum; fibrinogen is used up in forming fibrin threads during clotting. Albumins, globulins, nutrients and ions remain in serum.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-108","question":"Arrange the following events of blood coagulation in the correct sequence:\n(i) Prothrombin is converted into thrombin\n(ii) Factors released by injured tissue and platelets lead to formation of thrombokinase\n(iii) Fibrinogen is converted into fibrin threads\n(iv) Fibrin threads trap the formed elements to form a clot","options":["(i) → (ii) → (iii) → (iv)","(ii) → (iii) → (i) → (iv)","(iii) → (ii) → (i) → (iv)","(ii) → (i) → (iii) → (iv)"],"answer":3,"explanation":"Injury triggers a cascade that forms thrombokinase, which converts prothrombin to thrombin; thrombin converts fibrinogen into fibrin, whose network traps formed elements. Calcium ions are needed throughout.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-109","question":"Match the leucocyte with its role as described in NCERT.\nList I: (A) Basophils (B) Eosinophils (C) Monocytes (D) Lymphocytes\nList II: (1) Phagocytic cells that destroy foreign organisms entering the body (2) Secrete histamine, serotonin and heparin and are involved in inflammatory reactions (3) Responsible for the immune responses of the body (4) Resist infections and are associated with allergic reactions","options":["A-4, B-2, C-1, D-3","A-2, B-4, C-1, D-3","A-2, B-4, C-3, D-1","A-1, B-4, C-2, D-3"],"answer":1,"explanation":"Basophils secrete histamine, serotonin and heparin; eosinophils resist infections and are linked to allergy; neutrophils and monocytes are phagocytic; B and T lymphocytes mediate immunity.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-110","question":"A person's RBCs clump with anti-B serum but not with anti-A serum. If his plasma is mixed with RBCs from donors of different ABO groups, it will agglutinate the RBCs of groups:","options":["A and AB only","B and AB only","A, B and AB","O and B only"],"answer":0,"explanation":"Clumping only with anti-B means antigen B, so the person is group B and his plasma carries anti-A antibodies. Anti-A agglutinates RBCs bearing antigen A, i.e. groups A and AB.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-111","question":"In the human heart, the atrio-ventricular node (AVN) is located in the:","options":["right upper corner of the right atrium near the vena cava","lower right corner of the left atrium near the AV septum","lower left corner of the right atrium near the AV septum","upper part of the inter-ventricular septum below the atria"],"answer":2,"explanation":"The AVN lies in the lower left corner of the right atrium close to the atrio-ventricular septum. The right upper corner of the right atrium holds the SAN, and the AV bundle (not the node) runs into the inter-ventricular septum.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-112","question":"How many of the following are effects of parasympathetic neural signals on the human heart?\n(i) Decrease in the rate of heart beat\n(ii) Decrease in the speed of conduction of the action potential\n(iii) Increase in the strength of ventricular contraction\n(iv) Decrease in cardiac output\n(v) Increase in the release of adrenal medullary hormones","options":["Exactly 1","Exactly 2","Exactly 3","Exactly 4"],"answer":2,"explanation":"Parasympathetic signals reduce heart rate and the speed of conduction of the action potential, and thereby cardiac output: (i), (ii), (iv). A stronger ventricular contraction is a sympathetic effect, and adrenal medullary hormones are not released by parasympathetic signals.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-113","question":"A drug molecule absorbed into the blood capillaries of the ileum travels to the lungs. Which route does it follow?","options":["Hepatic portal vein → liver → hepatic artery → inferior vena cava → right atrium → right ventricle → pulmonary vein","Hepatic portal vein → liver → hepatic vein → inferior vena cava → right atrium → right ventricle → pulmonary artery","Hepatic vein → liver → hepatic portal vein → inferior vena cava → right atrium → right ventricle → pulmonary artery","Hepatic portal vein → liver → hepatic vein → superior vena cava → left atrium → left ventricle → pulmonary artery"],"answer":1,"explanation":"Intestinal blood first goes to the liver via the hepatic portal vein, leaves through the hepatic vein into the inferior vena cava, and reaches the lungs from the right ventricle via the pulmonary artery.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-114","question":"In a standard ECG, the end of the T-wave marks the:","options":["end of ventricular systole","end of atrial depolarisation","onset of ventricular contraction","beginning of atrial systole"],"answer":0,"explanation":"The T-wave represents return of the ventricles from the excited to the normal state (repolarisation), and NCERT notes that the end of the T-wave marks the end of systole. The P-wave relates to atria and the QRS to the onset of ventricular contraction.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-115","question":"Which statement about disorders of the circulatory system is correct as per NCERT?","options":["Heart failure is the same as cardiac arrest, in which the heart suddenly stops beating","Angina is the deposition of calcium, fat and cholesterol that narrows the coronary lumen","Coronary artery disease mainly affects the vessels that carry blood to the lungs","Heart failure is called congestive, as lung congestion is a main symptom"],"answer":3,"explanation":"Heart failure means the heart cannot pump enough blood; it is called congestive because lung congestion is a main symptom, and it is not the same as cardiac arrest or heart attack. Deposits in coronary arteries describe CAD (atherosclerosis); angina is chest pain from insufficient oxygen to heart muscle.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-116","question":"Which statement about the structure of the human kidney is INCORRECT?","options":["The inner concave surface has a notch, the hilum, through which ureter, blood vessels and nerves enter","Columns of Bertini are extensions of the medulla projecting into the cortex between the calyces","Inside the kidney, the broad funnel-shaped renal pelvis bears projections called calyces","The medulla is divided into a few conical masses, the medullary pyramids, projecting into the calyces"],"answer":1,"explanation":"Columns of Bertini (renal columns) are extensions of the CORTEX that dip in between the medullary pyramids, not medulla extending into cortex. The other descriptions match NCERT.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-117","question":"Which of the following statements about the nephrons of the human kidney are correct?\n(i) In the majority of nephrons the loop of Henle is short and extends very little into the medulla.\n(ii) In juxta medullary nephrons the loop of Henle runs deep into the medulla.\n(iii) The vasa recta is absent or highly reduced in juxta medullary nephrons.\n(iv) The Malpighian corpuscle, PCT and DCT are situated in the cortical region.\n(v) The efferent arteriole forms a fine capillary network around the renal tubule.","options":["(i), (ii), (iv) and (v) only","(i), (ii) and (iii) only","(ii), (iii), (iv) and (v) only","(i), (iv) and (v) only"],"answer":0,"explanation":"Most nephrons are cortical with short loops; juxta medullary nephrons have long loops. The vasa recta is absent or highly reduced in CORTICAL nephrons, not juxta medullary ones, so (iii) is wrong; the others are correct.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-118","question":"Relative to blood plasma, what is the nature of the filtrate at (X) Bowman's capsule, (Y) the bend of the loop of Henle of a juxta medullary nephron and (Z) the beginning of the distal convoluted tubule?","options":["X isotonic, Y hypotonic, Z hypertonic","X hypotonic, Y hypertonic, Z isotonic","X isotonic, Y isotonic, Z hypotonic","X isotonic, Y hypertonic, Z hypotonic"],"answer":3,"explanation":"The glomerular filtrate is isotonic; it gets concentrated in the water-permeable descending limb (hypertonic at the bend) and diluted in the water-impermeable ascending limb, which pumps out electrolytes, so it enters the DCT hypotonic.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-119","question":"The counter-current mechanism maintains a rising osmolarity towards the inner medullary interstitium. The approximate osmolarity reached there, and how concentrated human urine can become compared with the initial filtrate, are respectively:","options":["600 mOsmol L⁻¹; nearly two times","1200 mOsmol L⁻¹; nearly two times","1200 mOsmol L⁻¹; nearly four times","300 mOsmol L⁻¹; nearly three times"],"answer":2,"explanation":"Osmolarity rises from about 300 mOsmol L⁻¹ in the cortex to about 1200 mOsmol L⁻¹ in the inner medulla, mainly due to NaCl and urea, letting human kidneys make urine nearly four times as concentrated as the filtrate.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-120","question":"Protonephridia (flame cells) are the excretory structures in all of the following EXCEPT:","options":["Planaria","Earthworm","Rotifers","Amphioxus"],"answer":1,"explanation":"Protonephridia occur in Platyhelminthes (e.g. Planaria), rotifers, some annelids and the cephalochordate Amphioxus. The earthworm, though an annelid, excretes through nephridia — the trap is 'some annelids'.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-121","question":"How many of the following statements about the role of other organs in excretion are correct?\n(i) Human lungs remove about 200 mL of CO₂ per minute.\n(ii) The liver secretes bilirubin, biliverdin, cholesterol, degraded steroid hormones, vitamins and drugs into bile.\n(iii) Sweat contains NaCl, small amounts of urea and lactic acid.\n(iv) Sebaceous glands eliminate sterols, hydrocarbons and waxes through sebum.\n(v) The primary function of sweat is to eliminate nitrogenous wastes.","options":["Two","Three","Four","Five"],"answer":2,"explanation":"Statements (i)–(iv) are correct. Although sweat carries some wastes, its primary function is to provide a cooling effect on the body surface, so (v) is wrong.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-122","question":"Which pair is INCORRECTLY matched with its main mode of nitrogenous excretion?","options":["Marine fishes — ureotelic","Land snails — uricotelic","Aquatic insects — ammonotelic","Land amphibians — ammonotelic"],"answer":3,"explanation":"Mammals, many terrestrial amphibians and marine fishes are ureotelic; bony fishes, aquatic amphibians and aquatic insects are ammonotelic; reptiles, birds, land snails and insects are uricotelic.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-123","question":"An autoimmune disease destroys most of the oxyntic (parietal) cells of a patient's gastric glands. Besides reduced HCl secretion, the patient is most likely to show poor absorption of:","options":["vitamin A","vitamin B₁₂","vitamin D","folic acid"],"answer":1,"explanation":"Oxyntic cells secrete HCl and Castle's intrinsic factor, which is essential for the absorption of vitamin B₁₂. Peptic (chief) cells secrete pepsinogen.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-124","question":"Which statement about digestion in the human buccal cavity is correct?","options":["Salivary amylase hydrolyses about 30% of starch into the disaccharide maltose at pH 6.8","Salivary amylase hydrolyses about 70% of starch into glucose at an optimum pH of 7.8","Lysozyme present in saliva starts the digestion of food proteins by breaking peptide bonds","Electrolytes of saliva such as Na⁺, K⁺ and Cl⁻ hydrolyse maltose into glucose before swallowing"],"answer":0,"explanation":"About 30% of starch is hydrolysed in the mouth by salivary amylase (optimum pH 6.8) into maltose. Lysozyme acts as an antibacterial agent, and electrolytes do not digest sugars.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-125","question":"The sphincter of Oddi guards the opening of the:","options":["cystic duct into the gall bladder","pyloric stomach into the duodenum","hepato-pancreatic duct into the duodenum","ileum into the caecum of the large intestine"],"answer":2,"explanation":"The bile duct and pancreatic duct open together into the duodenum as the common hepato-pancreatic duct, guarded by the sphincter of Oddi. The stomach opening is guarded by the pyloric sphincter and the ileo-caecal junction by the ileo-caecal valve.","difficulty":"moderate","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-126","question":"Which statement about disorders of the digestive system is INCORRECT?","options":["In jaundice the liver is affected, and skin and eyes turn yellow due to deposition of bile pigments","Vomiting is the ejection of stomach contents through the mouth, controlled by a reflex centre in the medulla","In diarrhoea, abnormal frequency of bowel movement and increased liquidity of faeces reduce food absorption","In constipation, faeces are retained within the colon because bowel movements occur too frequently"],"answer":3,"explanation":"In constipation faeces are retained in the colon because bowel movements occur IRREGULARLY. The descriptions of jaundice, vomiting and diarrhoea match NCERT.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-127","question":"Which statement about the wall of the human alimentary canal is INCORRECT?","options":["The serosa is the outermost layer, made of thin mesothelium with some connective tissue","Irregular folds of the mucosa called villi occur in the stomach, and rugae in the small intestine","The muscularis has inner circular and outer longitudinal muscles, with an oblique layer in some regions","The sub-mucosal layer is formed of loose connective tissue containing nerves, blood and lymph vessels"],"answer":1,"explanation":"The labels are swapped: rugae are irregular mucosal folds in the stomach, while villi are small finger-like folds in the small intestine. The other three layers are correctly described.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-128","question":"Which statement about digestion in the human stomach is correct?","options":["HCl provides an acidic pH of about 1.8, at which pepsin converts proteins into proteoses and peptones","HCl provides an acidic pH of about 1.8, at which pepsin converts proteins directly into free amino acids","Pepsinogen is activated by enterokinase in the stomach and acts at an optimum pH of about 6.8","Rennin of adult gastric juice converts milk proteins into dipeptides at an alkaline pH of about 7.8"],"answer":0,"explanation":"HCl activates pepsinogen to pepsin and gives a pH of about 1.8; pepsin converts proteins into proteoses and peptones, not amino acids. Enterokinase acts in the intestine, and rennin is found in the gastric juice of infants.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-129","question":"Assertion (A): In the alveoli, CO₂ dissociates from carbamino-haemoglobin.\nReason (R): Binding of CO₂ with haemoglobin depends on the partial pressure of CO₂ and is also affected by pO₂; low pCO₂ and high pO₂ in the alveoli favour dissociation.","options":["Both A and R are true, but R is not the correct explanation of A","A is true but R is false","Both A and R are true and R is the correct explanation of A","A is false but R is true"],"answer":2,"explanation":"Carbamino-haemoglobin formation is governed by pCO₂, with pO₂ a major modifying factor: high pCO₂ and low pO₂ in tissues favour binding, while low pCO₂ and high pO₂ in the alveoli favour release, which explains A.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-130","question":"Arrange the steps of respiration in the correct order:\n(i) Diffusion of O₂ and CO₂ across the alveolar membrane\n(ii) Utilisation of O₂ by cells for catabolic reactions and release of CO₂\n(iii) Pulmonary ventilation (breathing)\n(iv) Diffusion of O₂ and CO₂ between blood and tissues\n(v) Transport of gases by the blood","options":["(iii) → (v) → (i) → (iv) → (ii)","(i) → (iii) → (v) → (iv) → (ii)","(iii) → (i) → (iv) → (v) → (ii)","(iii) → (i) → (v) → (iv) → (ii)"],"answer":3,"explanation":"Breathing brings air to the alveoli, gases diffuse across the alveolar membrane, blood transports them, they diffuse between blood and tissues, and finally cells use O₂ in catabolic reactions.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-131","question":"How many of the following statements about human blood are correct?\n(i) Formed elements constitute nearly 45 per cent of the blood.\n(ii) Plasma proteins constitute 6–8 per cent of the plasma.\n(iii) RBCs of most mammals are devoid of a nucleus and are biconcave in shape.\n(iv) In adults, RBCs are formed in the spleen, which is also their graveyard.\n(v) Lymphocytes are the most abundant WBCs, forming 60–65 per cent of total leucocytes.\n(vi) Platelets are cell fragments produced from megakaryocytes.","options":["Three","Four","Five","Six"],"answer":1,"explanation":"Statements (i), (ii), (iii) and (vi) are correct. In adults RBCs are formed in the red bone marrow (the spleen is only their graveyard), and neutrophils, not lymphocytes, form 60–65% of WBCs.","difficulty":"very-hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-132","question":"Which statement about the human heart is correct?","options":["The right atrio-ventricular opening is guarded by a valve of three muscular flaps or cusps","The left atrio-ventricular opening is guarded by the tricuspid valve formed of three cusps","The inter-atrial septum is thick-walled while the inter-ventricular septum is thin","Semilunar valves guard the openings of the ventricles into the pulmonary vein and aorta"],"answer":0,"explanation":"The tricuspid valve (three cusps) guards the right AV opening and the bicuspid (mitral) valve the left. The inter-atrial septum is thin and the inter-ventricular septum thick, and semilunar valves lie at the openings into the pulmonary ARTERY and aorta.","difficulty":"hard","source":"NEET UG"},
  {"id":"bio-human-physiology-systems-133","question":"The human kidneys filter about 1100–1200 mL of blood per minute. This is roughly what fraction of the blood pumped out by each ventricle of the heart per minute?","options":["One-half","One-tenth","One-third","One-fifth"],"answer":3,"explanation":"NCERT states that on average 1100–1200 mL of blood is filtered by the kidneys per minute, which constitutes roughly one-fifth of the blood pumped out by each ventricle (cardiac output about 5–5.5 L/min).","difficulty":"hard","source":"NEET UG"},
];

export default questions;
